    /** The language tags with a table, lower case. */
    static final String[] LANGUAGES = {"de", "es", "in", "ko", "pt-rbr", "tr"};

    /**
     * The table for one language tag, or null when nothing was translated into it.
     * A language with two ISO codes answers to both, because Android reports the
     * legacy one and a desktop JVM reports the new one.
     */
    static Map<String, String> of(String language) {
        switch (language) {
            case "de":
                return buildDe();
            case "es":
                return buildEs();
            case "in":
            case "id":
                return buildIn();
            case "ko":
                return buildKo();
            case "pt-rbr":
                return buildPt_rBR();
            case "tr":
                return buildTr();
            default:
                return null;
        }
    }

